WITH valid AS (SELECT *, UPPER(country) AS country_upper, COALESCE(browser, 'UNKNOWN') AS browser_clean FROM sessions WHERE started_at >= TIMESTAMP '2023-06-05 12:00:00' AND device IN ('desktop', 'mobile', 'tablet')), gaps AS (SELECT *, CASE WHEN LAG(started_at) OVER (PARTITION BY device ORDER BY started_at, id) IS NULL OR started_at > LAG(started_at) OVER (PARTITION BY device ORDER BY started_at, id) + INTERVAL '14' DAY THEN 1 ELSE 0 END AS session_start_flag FROM valid), islands AS (SELECT id, device, browser, started_at, country, country_upper, browser_clean, SUM(session_start_flag) OVER (PARTITION BY device ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps) SELECT DATE_TRUNC('WEEK', started_at) AS week_start, device, APPROX_PERCENTILE(island_id, 0.5) AS island_id_p50, SORT_ARRAY(COLLECT_SET(browser)) AS browser_list, AVG(island_id) FILTER (WHERE country = 'SG') AS sg_avg_island_id FROM islands GROUP BY ROLLUP (DATE_TRUNC('WEEK', started_at), device) HAVING island_id_p50 > 0 ORDER BY device DESC
